// TestActionNames asserts every announced flow action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Choose,
		provider.Complete,
		provider.Degraded,
		provider.Failed,
		provider.Gather,
		provider.Subgraph,
		provider.WaitUntil,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

